   547      // parse all elements
   548      if (EEST_INVALID == pcElement->eSemantic || pcElement->alProperties.empty()) {
   549          // if the element has an unknown semantic we can skip all lines
   550          // However, there could be comments
   551          for (unsigned int i = 0; i < pcElement->NumOccur; ++i) {
